static uint32_t ys_symbol_hash_value(const WCHAR *text) {
    uint32_t hash = 2166136261u;
    if (!text) return 0u;
    while (*text) { hash ^= (uint16_t)*text++; hash *= 16777619u; }
    return hash;
}
int ys_symbol_index_from_text(const WCHAR *text) {
    const uint32_t mask = 65535u;
    uint32_t slot, start, stored;
    if (!text || !text[0]) return -1;
    slot = ys_symbol_hash_value(text) & mask;
    start = slot;
    do {
        stored = g_ys_symbol_hash_table[slot];
        if (!stored) return -1;
        if (wcscmp(ys_symbol_text(stored - 1u), text) == 0) return (int)(stored - 1u);
        slot = (slot + 1u) & mask;
    } while (slot != start);
    return -1;
}

